def match(pattern: str, text: str) -> bool:
    """
    Implements a recursive backtracking algorithm for basic regex matching.
    Supports literal characters, '.' (matches any character), '*' (zero or more),
    and '+' (one or more).
    """
    def is_match(p_idx: int, t_idx: int) -> bool:
        if p_idx == len(pattern) and t_idx == len(text):
            return True

        if p_idx < len(pattern) and p_idx + 1 < len(pattern) and pattern[p_idx + 1] == '*':
            # Check for zero occurrence of the preceding element
            if is_match(p_idx + 2, t_idx):
                return True
            # Check for one or more occurrences if matches
            while t_idx < len(text) and (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.'):
                if is_match(p_idx + 2, t_idx + 1):
                    return True
                t_idx += 1

        if p_idx < len(pattern) and t_idx < len(text):
            if pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.':
                return is_match(p_idx + 1, t_idx + 1)

        return False

    return is_match(0, 0)

